2762	    pub fn parse_window_frame(&mut self) -> Result<WindowFrame, ParserError> {
2763	        let units = self.parse_window_frame_units()?;
2764	        let (start_bound, end_bound) = if self.parse_keyword(Keyword::BETWEEN) {
2765	            let start_bound = self.parse_window_frame_bound()?;
