mkdir -p examples && cat > examples/kwtest.rs <<'EOF'
fn main() {
    let g = sqlparser::dialect::GenericDialect {};
    let ok = [
        // quoted identifiers that collide with the new keyword / clause
        r#"SELECT "others" FROM t"#,
        r#"SELECT "EXCLUDE" FROM t"#,
        r#"SELECT sum(x) OVER "w" FROM t WINDOW "w" AS (ROWS 1 PRECEDING EXCLUDE TIES)"#,
        // EXCLUDE used elsewhere (existing usages unaffected)
        "SELECT * EXCLUDE (a) FROM t",          // wildcard exclude (generic supports)
        "SELECT exclude FROM t",                 // column named exclude
        // window frame bound exprs still parse
        "SELECT sum(x) OVER (ROWS BETWEEN (1+2)*3 PRECEDING AND f(y) FOLLOWING EXCLUDE GROUP) FROM t",
        "SELECT sum(x) OVER (RANGE BETWEEN INTERVAL '1' DAY PRECEDING AND INTERVAL '2' DAY FOLLOWING EXCLUDE NO OTHERS) FROM t",
        // EXCLUDE right before closing paren -> error
    ];
    for sql in ok {
        match sqlparser::parser::Parser::parse_sql(&g, sql) {
            Ok(ast) => println!("OK: {sql}\n  => {}", ast[0]),
            Err(e) => println!("ERR: {sql} => {e}"),
        }
    }
    for sql in [
        "SELECT sum(x) OVER (ROWS 1 PRECEDING EXCLUDE) FROM t",
        "SELECT sum(x) OVER (ROWS 1 PRECEDING EXCLUDE CURRENT ROW EXCLUDE NO OTHERS) FROM t",
    ] {
        match sqlparser::parser::Parser::parse_sql(&g, sql) {
            Ok(ast) => println!("UNEXPECTED OK: {sql} => {}", ast[0]),
            Err(e) => println!("expected ERR: {sql} => {e}"),
        }
    }
    // others as identifier in mysql
    let m = sqlparser::dialect::MySqlDialect {};
    println!("mysql SELECT others FROM t: {:?}", sqlparser::parser::Parser::parse_sql(&m, "SELECT others FROM t").map(|a| a[0].to_string()));
}
EOF
